  "chatgpt.privacy_center.locked_chats.description.device_unlock": "\u4F7F\u7528 PIN \u7801\u3001\u4EBA\u8138\u8BC6\u522B\u6216\u6307\u7EB9\u8BC6\u522B\u4FDD\u62A4\u804A\u5929\u3002",
  "chatgpt.privacy_center.locked_chats.faq.how.answer.device_unlock": "\u9501\u5B9A\u804A\u5929\u540E\uFF0C\u5176\u6807\u9898\u548C\u5185\u5BB9\u5C06\u4E0D\u4F1A\u663E\u793A\u5728\u5E38\u89C4\u4FA7\u8FB9\u680F\u3001\u5386\u53F2\u8BB0\u5F55\u548C\u641C\u7D22\u7ED3\u679C\u4E2D\u3002\u4F60\u9700\u8981\u4F7F\u7528 PIN \u7801\u6216\u8BBE\u5907\u89E3\u9501\u65B9\u5F0F\uFF08\u4F8B\u5982 Face ID \u6216\u6307\u7EB9\u8BC6\u522B\uFF09\u624D\u80FD\u6253\u5F00\u804A\u5929\u3002",
  "chatgpt.privacy_center.locked_chats.faq.how.question": "\u9501\u5B9A\u804A\u5929\u529F\u80FD\u5982\u4F55\u8FD0\u4F5C\uFF1F",
  "chatgpt.privacy_center.locked_chats.faq.memory.answer": "\u9501\u5B9A\u804A\u5929\u53EF\u4EE5\u4F7F\u7528 ChatGPT \u4ECE\u666E\u901A\u804A\u5929\u548C\u9501\u5B9A\u804A\u5929\u4E2D\u8BB0\u4F4F\u7684\u4FE1\u606F\u3002\u9501\u5B9A\u804A\u5929\u540E\uFF0C\u5176\u4E2D\u7684\u65B0\u6D88\u606F\u53EF\u4EE5\u7528\u4E8E\u4E3A\u5176\u4ED6\u9501\u5B9A\u804A\u5929\u63D0\u4F9B\u4E2A\u6027\u5316\u4F53\u9A8C\uFF0C\u4F46\u4E0D\u4F1A\u7528\u4E8E\u666E\u901A\u804A\u5929\u3002\u9501\u5B9A\u804A\u5929\u4E0D\u4F1A\u5220\u9664 ChatGPT \u53EF\u80FD\u5DF2\u7ECF\u8BB0\u4F4F\u7684\u4FE1\u606F\u3002",
  "chatgpt.privacy_center.locked_chats.faq.memory.question": "\u8BB0\u5FC6\u529F\u80FD\u5982\u4F55\u4E0E\u9501\u5B9A\u804A\u5929\u914D\u5408\u4F7F\u7528\uFF1F",
  "chatgpt.privacy_center.locked_chats.faq.opening.answer": "\u662F\u7684\u3002\u5B83\u4F1A\u4E00\u76F4\u4FDD\u6301\u9501\u5B9A\u72B6\u6001\uFF0C\u76F4\u5230\u4F60\u9009\u62E9\u5C06\u5176\u6539\u4E3A\u666E\u901A\u804A\u5929\u3002",
