  "chatgpt.privacy_center.memory.faq.delete.answer": "\u5728\u8BB0\u5FC6\u6458\u8981\u5E95\u90E8\u7684\u6587\u672C\u6846\u4E2D\u8F93\u5165\u4F60\u5E0C\u671B\u66F4\u6539\u7684\u5185\u5BB9\uFF0C\u6458\u8981\u5C31\u4F1A\u76F8\u5E94\u66F4\u65B0\u3002\u4F60\u4E5F\u53EF\u4EE5\u9009\u4E2D\u8BB0\u5FC6\u6458\u8981\u4E2D\u7684\u4EFB\u610F\u6587\u672C\uFF0C\u8FDB\u884C\u9488\u5BF9\u6027\u66F4\u6B63\u3002\u8981\u5F7B\u5E95\u5220\u9664 ChatGPT \u53EF\u80FD\u8BB0\u4F4F\u7684\u5173\u4E8E\u4F60\u7684\u67D0\u9879\u4FE1\u606F\uFF0C\u8BF7\u5220\u9664\u6240\u6709\u5305\u542B\u8BE5\u4FE1\u606F\u7684\u6765\u6E90\uFF0C\u5305\u62EC\u4EE5\u5F80\u7684\u66F4\u6539\u3001\u5DF2\u5F52\u6863\u7684\u804A\u5929\u3001\u6587\u4EF6\u548C\u8BB0\u5FC6\u6458\u8981\uFF0C\u5E76\u65AD\u5F00\u6240\u6709\u53EF\u80FD\u5305\u542B\u8BE5\u4FE1\u606F\u7684\u5DF2\u8FDE\u63A5\u5E94\u7528\u3002",
  "chatgpt.privacy_center.memory.faq.delete.question": "\u5982\u679C\u6211\u4E0D\u60F3\u8BA9 ChatGPT \u8BB0\u4F4F\u5173\u4E8E\u6211\u7684\u67D0\u4E9B\u4FE1\u606F\uFF0C\u8BE5\u600E\u4E48\u529E\uFF1F",
  "chatgpt.privacy_center.memory.faq.how.answer": "\u542F\u7528\u540E\uFF0C\u8BB0\u5FC6\u529F\u80FD\u4F1A\u5E2E\u52A9 ChatGPT \u81EA\u52A8\u8BB0\u4F4F\u4F60\u7684\u804A\u5929\u3001\u6587\u4EF6\u548C\u5DF2\u8FDE\u63A5\u5E94\u7528\u4E2D\u7684\u6709\u7528\u80CC\u666F\u4FE1\u606F\uFF0C\u4E3A\u4F60\u63D0\u4F9B\u4E2A\u6027\u5316\u4F53\u9A8C\uFF0C\u8BA9\u4F60\u4E0D\u5FC5\u9891\u7E41\u91CD\u590D\u8BF4\u660E\u3002\u5982\u679C\u4F60\u4E0D\u60F3\u4F7F\u7528\u6216\u66F4\u65B0\u8BB0\u5FC6\uFF0C\u8BF7\u4F7F\u7528 <temporaryChat>\u4E34\u65F6\u804A\u5929</temporaryChat>\u3002",
  "chatgpt.privacy_center.memory.faq.how.question": "\u8BB0\u5FC6\u529F\u80FD\u5982\u4F55\u8FD0\u4F5C\uFF1F",
  "chatgpt.privacy_center.memory.faq.view.answer": "\u4F60\u53EF\u4EE5\u968F\u65F6\u8BE2\u95EE ChatGPT \u8BB0\u4F4F\u4E86\u54EA\u4E9B\u5173\u4E8E\u4F60\u7684\u4FE1\u606F\uFF0C\u6216\u67E5\u770B\u4F60\u7684 <memorySummary>\u8BB0\u5FC6\u6458\u8981</memorySummary>\u3002",
  "chatgpt.privacy_center.memory.faq.view.question": "\u5982\u4F55\u67E5\u770B ChatGPT \u8BB0\u4F4F\u4E86\u54EA\u4E9B\u5173\u4E8E\u6211\u7684\u4FE1\u606F\uFF1F",
  "chatgpt.privacy_center.memory.title": "\u8BB0\u5FC6",
  "chatgpt.privacy_center.model_improvement.card_description": "\u9009\u62E9\u662F\u5426\u4F7F\u7528\u4F60\u7684\u804A\u5929\u5185\u5BB9\u6765\u5E2E\u52A9\u6539\u8FDB OpenAI \u672A\u6765\u7684\u6A21\u578B\u3002",
  "chatgpt.privacy_center.model_improvement.description": "\u9009\u62E9\u662F\u5426\u4F7F\u7528\u4F60\u7684\u804A\u5929\u5185\u5BB9\u6765\u5E2E\u52A9\u6539\u8FDB OpenAI \u7684\u6A21\u578B\u3002",
  "chatgpt.privacy_center.model_improvement.faq.disable.answer": "\u4F60\u4ECA\u540E\u7684\u804A\u5929\u4E0D\u4F1A\u7528\u4E8E\u6539\u8FDB OpenAI \u7684\u6A21\u578B\u3002\u5173\u95ED\u6B64\u8BBE\u7F6E\u4E0D\u4F1A\u5220\u9664\u4F60\u7684\u804A\u5929\uFF0C\u4E5F\u4E0D\u4F1A\u5F71\u54CD\u804A\u5929\u5386\u53F2\u8BB0\u5F55\u6216\u66F4\u6539\u8BB0\u5FC6\u8BBE\u7F6E\u3002\u5982\u679C\u4F60\u4E0D\u5E0C\u671B ChatGPT \u8BB0\u4F4F\u4F60\u95EE\u8FC7\u7684\u5185\u5BB9\uFF0C\u4E5F\u53EF\u4EE5\u4F7F\u7528\u4E34\u65F6\u804A\u5929\u3002",
