  "scheduled.landing.description": "ChatGPT \u53EF\u4EE5\u5E2E\u4F60\u5904\u7406\u6301\u7EED\u6027\u4EFB\u52A1\uFF0C\u8BA9\u4F60\u4E0D\u5FC5\u4EB2\u81EA\u52A8\u624B\u3002",
  "scheduled.landing.example.email.description": "\u67E5\u770B\u6211\u7684\u90AE\u4EF6\uFF0C\u5E76\u544A\u77E5\u6211\u9700\u8981\u5173\u6CE8\u7684\u4E8B\u9879\u3002",
  "scheduled.landing.example.email.prompt": "\u5E2E\u6211\u8BBE\u7F6E\u90AE\u4EF6\u76D1\u63A7\uFF0C\u6807\u8BB0\u9700\u8981\u6211\u5173\u6CE8\u7684\u90AE\u4EF6\u3002\u5728\u5B89\u6392\u5B9A\u65F6\u4EFB\u52A1\u4E4B\u524D\uFF0C\u5148\u95EE\u6211\u8981\u76D1\u63A7\u54EA\u4E2A\u6536\u4EF6\u7BB1\u6216\u54EA\u4E9B\u53D1\u4EF6\u4EBA\u7684\u90AE\u4EF6\u3001\u54EA\u4E9B\u90AE\u4EF6\u7B97\u91CD\u8981\uFF0C\u4EE5\u53CA\u591A\u4E45\u68C0\u67E5\u4E00\u6B21\u3002\u5982\u6709\u9700\u8981\uFF0C\u5E2E\u6211\u8FDE\u63A5\u7535\u5B50\u90AE\u7BB1\u3002",
  "scheduled.landing.example.email.title": "\u76D1\u63A7\u7535\u5B50\u90AE\u7BB1",
  "scheduled.landing.example.finance.description": "\u56DE\u987E\u6211\u6700\u8FD1\u7684\u652F\u51FA\uFF0C\u770B\u770B\u6709\u4EC0\u4E48\u9700\u8981\u6CE8\u610F\u3002",
  "scheduled.landing.example.finance.prompt": "\u5E2E\u6211\u8BBE\u7F6E\u6BCF\u5468\u8D22\u52A1\u56DE\u987E\uFF0C\u68B3\u7406\u6211\u6700\u8FD1\u7684\u652F\u51FA\u3001\u5B9A\u671F\u6263\u8D39\uFF0C\u4EE5\u53CA\u4EFB\u4F55\u9700\u8981\u5173\u6CE8\u7684\u4E8B\u9879\u3002\u5B89\u6392\u65E5\u7A0B\u524D\uFF0C\u5148\u95EE\u6211\u60F3\u4F7F\u7528\u54EA\u4E9B\u8D22\u52A1\u4FE1\u606F\uFF0C\u4EE5\u53CA\u54EA\u4E00\u5929\u3001\u51E0\u70B9\u65B9\u4FBF\u3002",
  "scheduled.landing.example.finance.title": "\u6BCF\u5468\u8D22\u52A1\u72B6\u51B5\u66F4\u65B0",
  "scheduled.landing.example.flights.description": "\u4E3A\u5373\u5C06\u542F\u7A0B\u7684\u65C5\u884C\u5BFB\u627E\u6700\u5212\u7B97\u7684\u673A\u7968\u3002",
  "scheduled.landing.example.flights.prompt": "\u5E2E\u6211\u4E3A\u5373\u5C06\u5230\u6765\u7684\u65C5\u884C\u8BBE\u7F6E\u673A\u7968\u4EF7\u683C\u76D1\u6D4B\u3002\u8BF7\u8BE2\u95EE\u6211\u7684\u51FA\u53D1\u5730\u3001\u76EE\u7684\u5730\u3001\u51FA\u884C\u65E5\u671F\u3001\u9884\u7B97\uFF0C\u4EE5\u53CA\u67E5\u8BE2\u9891\u7387\u3002\u627E\u5230\u7B26\u5408\u6761\u4EF6\u7684\u822A\u73ED\u65F6\u901A\u77E5\u6211\u3002",
  "scheduled.landing.example.flights.title": "\u4E3A\u65C5\u884C\u641C\u7D22\u822A\u73ED",
  "scheduled.landing.example.meal.description": "\u89C4\u5212\u4E00\u5468\u7684\u9910\u98DF\uFF0C\u5E76\u5217\u51FA\u98DF\u6750\u91C7\u8D2D\u6E05\u5355\u3002",
  "scheduled.landing.example.meal.prompt": "\u5E2E\u6211\u5236\u5B9A\u6BCF\u5468\u9910\u98DF\u8BA1\u5212\uFF0C\u5E76\u9644\u4E0A\u8D2D\u7269\u6E05\u5355\u3002\u5728\u5B89\u6392\u5B9A\u65F6\u4EFB\u52A1\u4E4B\u524D\uFF0C\u5148\u8BE2\u95EE\u6211\u7684\u996E\u98DF\u504F\u597D\u3001\u5BB6\u5EAD\u4EBA\u6570\uFF0C\u4EE5\u53CA\u5E0C\u671B\u4F55\u65F6\u6536\u5230\u8BA1\u5212\u3002",
  "scheduled.landing.example.meal.title": "\u6BCF\u5468\u996E\u98DF\u8BA1\u5212",
  "scheduled.landing.example.sleep.description": "\u8DDF\u8E2A\u6211\u7684\u7761\u7720\u8D28\u91CF\uFF0C\u5E76\u5E2E\u52A9\u6211\u6539\u5584\u751F\u6D3B\u4E60\u60EF\u3002",
  "scheduled.landing.example.sleep.prompt": "\u5E2E\u6211\u8BBE\u7F6E\u5B9A\u671F\u7761\u7720\u6253\u5361\u3002\u5B89\u6392\u65E5\u7A0B\u524D\uFF0C\u8BF7\u5148\u8BE2\u95EE\u6211\u7684\u7761\u7720\u76EE\u6807\u3001\u6211\u613F\u610F\u5206\u4EAB\u7684\u4FE1\u606F\u5185\u5BB9\uFF0C\u4EE5\u53CA\u6211\u671F\u671B\u7684\u6253\u5361\u65F6\u95F4\u3002",
  "scheduled.landing.example.sleep.title": "\u7761\u7720\u6307\u5BFC",
