  "settingsModal.trustedContacts.infoModal.introBodyPrimary.v2": "\u5F53\u4F60\u611F\u5230\u538B\u529B\u5F88\u5927\u65F6\uFF0C\u53EF\u80FD\u5F88\u96BE\u4E3B\u52A8\u5BFB\u6C42\u5E2E\u52A9\u3002\u6709\u4E00\u4F4D<bold>\u53D7\u4FE1\u4EFB\u8054\u7CFB\u4EBA</bold>\uFF0C\u53EF\u4EE5\u8BA9\u4F60\u66F4\u5BB9\u6613\u4ECE\u719F\u6089\u4F60\u7684\u4EBA\u90A3\u91CC\u83B7\u5F97\u652F\u6301\u3002",
