  "trustedContact.notification.alert.modal.bodyPrimary": "\u5C0F\u5C0F\u7684\u4E3E\u52A8\uFF0C\u6BD4\u5982\u4E3B\u52A8\u8054\u7CFB\u3001\u8868\u8FBE\u5173\u5FC3\uFF0C\u6216\u5E2E\u52A9\u5BF9\u65B9\u83B7\u5F97\u8FDB\u4E00\u6B65\u652F\u6301\uFF0C\u90FD\u53EF\u80FD\u5E26\u6765\u6709\u610F\u4E49\u7684\u6539\u53D8\u3002\u4F60\u53EF\u4EE5\u5728<helpCenterLink>\u8FD9\u91CC</helpCenterLink>\u627E\u5230\u4E00\u4E9B\u5C0F\u8D34\u58EB\uFF0C\u4E86\u89E3\u5982\u4F55\u4EE5\u5173\u6000\u548C\u652F\u6301\u7684\u65B9\u5F0F\u5F00\u542F\u5BF9\u8BDD\u3002",
  "trustedContact.notification.alert.modal.bodySecondary.v2": "\u4F60\u65E0\u9700\u627F\u62C5\u4FDD\u969C\u5BF9\u65B9\u5B89\u5168\u7684\u8D23\u4EFB\uFF0C\u4E5F\u4E0D\u5FC5\u5145\u5F53\u5FC3\u7406\u54A8\u8BE2\u5E08\u6216\u5371\u673A\u5E72\u9884\u4EBA\u5458\u2014\u2014\u4F60\u662F\u66F4\u5E7F\u6CDB\u7684\u652F\u6301\u7F51\u7EDC\u4E2D\u7684\u4E00\u5458\u3002\u5982\u9700\u83B7\u53D6\u66F4\u591A\u8D44\u6E90\uFF0C\u8BF7\u8BBF\u95EE\u6211\u4EEC\u7684<helpCenterLink>\u5E2E\u52A9\u4E2D\u5FC3</helpCenterLink>\u3002",
  "trustedContact.notification.alert.modal.bodyTertiary.v2": "\u6211\u4EEC\u7684\u7CFB\u7EDF\u672A\u5FC5\u80FD\u5B8C\u5168\u51C6\u786E\u5730\u7406\u89E3\u6BCF\u4E00\u6BB5\u5BF9\u8BDD\uFF0C\u4E5F\u672A\u5FC5\u80FD\u53CD\u6620 {trustedContactName} \u6B64\u523B\u7684\u611F\u53D7\u3002\u5982\u679C\u4F60\u62C5\u5FC3\u5B58\u5728\u8FEB\u5728\u7709\u776B\u7684\u5B89\u5168\u98CE\u9669\uFF0C\u53EF\u4EE5\u968F\u65F6\u62E8\u6253\u5F53\u5730\u7D27\u6025\u670D\u52A1\u7535\u8BDD\uFF0C\u6216\u8054\u7CFB<helpCenterLink>\u5371\u673A\u63F4\u52A9\u70ED\u7EBF</helpCenterLink>\u3002",
  "trustedContact.notification.alert.modal.howYouCanHelpHeading": "\u4F60\u53EF\u4EE5\u600E\u6837\u63D0\u4F9B\u5E2E\u52A9",
