  "trustedContact.publicLink.accept.primaryButton": "\u63A5\u53D7",
  "trustedContact.publicLink.accept.summary.v2": "\u5982\u679C\u67D0\u4EBA\u8C08\u53CA\u81EA\u6740\uFF0C\u4E14\u8A00\u8BED\u8868\u660E\u5B58\u5728\u4E25\u91CD\u7684\u5B89\u5168\u98CE\u9669\uFF0C\u6709\u4E00\u4F4D\u53D7\u4FE1\u4EFB\u8054\u7CFB\u4EBA\u53EF\u4EE5\u8BA9\u4ED6\u4EEC\u66F4\u5BB9\u6613\u8054\u7CFB\u5230\u670B\u53CB\u3001\u5BB6\u4EBA\u6216\u503C\u5F97\u4FE1\u4EFB\u7684\u6210\u5E74\u4EBA\u3002",
